public void registerDog(Animal animal) {
    if (animal instanceof Dog dog && dog.weightKg() > 25) {
        System.out.println("Large dog: " + dog.name());
    }
    if (!(animal instanceof Dog dog)) {
        return;
    }
    System.out.println("Registered: " + dog.name());
}

public String handle(PaymentEvent event) {
    return switch (event) {
        case PaymentSuccess s when s.amount() > 10_000 ->
            "Flagged high value: " + s.transactionId();
        case PaymentSuccess s -> "Settled: " + s.transactionId();
        case PaymentFailed f -> "Failed: " + f.errorCode();
        case null -> "No event provided";
    };
}
